<div class="toolbar"><div><p class="muted">Manage team access and roles.</p></div><a class="btn primary" href="/admin/users/create">+ Add user</a></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last login</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($items as $u):?><tr><td><div class="user-cell"><span class="avatar small-avatar"><?= e(mb_strtoupper(mb_substr($u['name'],0,1))) ?></span><div><strong><?= e($u['name']) ?></strong><small><?= e($u['email']) ?></small></div></div></td><td><span class="badge neutral"><?= e($u['role']) ?></span></td><td><span class="badge <?= $u['status']==='active'?'success':'danger' ?>"><?= e($u['status']) ?></span></td><td class="muted"><?= e($u['last_login_at']??'Never') ?></td><td class="muted"><?= e($u['created_at']) ?></td><td><div class="actions"><a class="btn small" href="/admin/users/<?= (int)$u['id'] ?>/edit">Edit</a><?php if((int)$u['id']!==(int)($currentUser['id']??0)):?><form method="post" action="/admin/users/<?= (int)$u['id'] ?>/delete" data-confirm="Delete this user?"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>